question.solution:
state = {'left': True, 'center': True, 'right': False}


def toggle(state, name):
    if name not in state:
        return dict(state)
    updated = dict(state)
    updated[name] = not state[name]
    return updated


def only(state, name):
    if name not in state:
        return dict(state)
    return {key: (key == name) for key in state}


def apply_events(state, events):
    current = dict(state or {})
    for event in events or []:
        if not event:
            continue
        kind = event[0]
        if kind == 'toggle' and len(event) >= 2:
            current = toggle(current, event[1])
        elif kind == 'only' and len(event) >= 2:
            current = only(current, event[1])
        elif kind == 'set' and len(event) >= 3:
            if event[1] in current:
                current = dict(current)
                current[event[1]] = bool(event[2])
    return current


print(apply_events(state, [('toggle', 'right')]))
print(apply_events(state, [('only', 'left'), ('toggle', 'right')]))
print(apply_events(state, [('set', 'center', 0), ('nope', 'x')]))
print('原状态：', state)
